workspace "Home Energy Management Platform" "C4 model of the home energy management platform" {

    model {

        homeowner = person "Homeowner" "Uses the platform to manage the household's energy use and costs"

        energyManager = system "Energy Manager" "Home energy management platform, owned and operated by our company" {
            dashboard = component "Dashboard Web App" "Where homeowners see consumption and costs" "Web Application"
            scheduler = component "Scheduling Service" "Plans charging and heating" "Service"
            ratesLibrary = component "Rates Library" "Computes energy prices from tariff and time of day" "Library"
            database = component "Database" "Stores meter readings and schedules" "Database"
        }

        smartMeterProvider = system "Smart Meter Provider" "Provides live meter readings; operated by a different organization" "External"

        homeowner -> dashboard "Views consumption and costs"
        dashboard -> ratesLibrary "Embeds"
        scheduler -> ratesLibrary "Embeds"
        scheduler -> smartMeterProvider "Fetches live meter readings"
        scheduler -> database "Stores meter readings and schedules"
    }

    views {
        systemContext energyManager "SystemContext" "System context diagram for the Energy Manager" {
            include *
            autoLayout
        }

        container energyManager "Containers" "Container diagram for the Energy Manager" {
            include *
            autoLayout
        }
    }

    themes default
}

